              "text": "[Document context]\nTitle: Histogram analytics implementation\nSource: Langfuse pinned source\nPath: /code/langfuse/web/src/features/dashboard/lib/score-analytics-utils.ts\nWorkspace: person/sana-farid/issue-15208-histogram\n\nimport { type DashboardDateRangeAggregationOption } from \"@/src/utils/date-range-utils\";\nimport { type DatabaseRow } from \"@/src/server/api/services/sqlInterface\";\nimport {\n  type CategoryCounts,\n  type ChartBin,\n  type HistogramBin,\n} from \"@/src/features/scores/types\";\nimport { type RouterOutputs } from \"@/src/utils/api\";\n\nexport const RESOURCE_METRICS = [\n  {\n    key: \"latency\",\n    value: \"Latency\",\n    objectKey: \"avgLatency\",\n    label: \"Latency\",\n    maxFractionDigits: 2,\n  },\n  {\n    key: \"cost\",\n    value: \"Cost\",\n    objectKey: \"avgTotalCost\",\n    label: \"Average Total Cost ($)\",\n    maxFractionDigits: 5,\n  },\n];\n\n// numeric score analytics helpers\nfunction round(value: number, precision = 2) {\n  return parseFloat(value.toFixed(precision));\n}\n\nexport function uniqueAndSort(labels: string[]): string[] {\n  return Array.from(new Set(labels)).sort();\n}\n\nfunction computeBinSize(\n  minBins: number,\n  maxBins: number,\n  range: number,\n  valueCount: number,\n) {\n  return range === 0\n    ? 1\n    : Math.min(Math.max(minBins, Math.floor(Math.sqrt(valueCount))), maxBins);\n}\n\nexport function createHistogramData(\n  data: DatabaseRow[],\n  minBins = 1,\n  maxBins = 10,\n) {\n  const numericScoreValues = data.map((item) => item.value as number);\n  if (!Boolean(numericScoreValues.length))\n    return { chartData: [], chartLabels: [] };\n\nconst min = Math.min(...numericScoreValues);\n  const range = Math.max(...numericScoreValues) - min;\n  const bins = computeBinSize(\n    minBins,\n    maxBins,\n    range,\n    numericScoreValues.length,\n  );\n  const binSize = range / bins || 1;",
