              "text": "[Document context]\nTitle: Histogram analytics regression tests\nSource: Langfuse pinned source\nPath: /code/langfuse/web/src/features/dashboard/lib/score-analytics-utils.clienttest.ts\nWorkspace: person/sana-farid/issue-15208-histogram\n\nimport { createHistogramData } from \"@/src/features/dashboard/lib/score-analytics-utils\";\n\ndescribe(\"createHistogramData\", () => {\n  it(\"bins the 0.857 regression value by raw magnitude\", () => {\n    const result = createHistogramData(\n      [0, 0.857, 0.86, 1].map((value) => ({ value })),\n      7,\n      7,\n    );\n\nexpect(result.chartData.map(({ count }) => count)).toEqual([\n      1, 0, 0, 0, 0, 1, 2,\n    ]);\n  });\n\nit(\"keeps narrow-range display labels distinct and preserves counts\", () => {\n    const result = createHistogramData(\n      [0.855, 0.857, 0.858, 0.861].map((value) => ({ value })),\n    );\n\nexpect(result.chartData.map(({ binLabel }) => binLabel)).toEqual([\n      \"[0.855, 0.858]\",\n      \"[0.858, 0.861]\",\n    ]);\n    expect(result.chartData.reduce((sum, { count }) => sum + count, 0)).toBe(4);\n  });\n});",
