          isTotal: true,
        });","content_hash":"319896720f1962cc7731f707a222d74795c7f7d639a01f7eef0f2dc3ddefdf08","chunk_metadata":{"ordinal":9,"document_path":"/code/langfuse/web/src/__tests__/server/pivot-table-utils.servertest.ts","document_kind":"source","workspace":"person/sana-farid/issue-15208-weighted","team":""}}},"conflict_id":null,"change_id":"qdrant:1a360449d231c6dcd6ab8d5a"},{"table":"knowledge","key":{"id":"enterprise_5a5666d4329b062e81336635:00010"},"change":"modified","before":{"id":"enterprise_5a5666d4329b062e81336635:00010","vector":{"bm25":{"indices":[62336270,70186382,212648289,248443073,308051045,324090866,401840070,448220673,454222729,481329573,493749041,520409122,548955463,585061349,601300722,679967618,757424159,766710245,772165269,806276788,844849131,923101995,926244272,1009084850,1030514789,1144259690,1150483835,1177953192,1263925004,1264846464,1303077409,1308688855,1424671076,1480764286,1519078073,1539641452,1646993830,1676405609,1678348498,1701701189,1769147305,1780814776,1810453357,1853176582,1972195609,2003180332,2027491601,2074315840,2119396515,2126841918,2128973781],"values":[1.416499,1.416499,1.8575197,1.416499,1.416499,1.416499,1.416499,1.416499,1.416499,1.7233782,1.416499,1.416499,1.7233782,1.416499,1.416499,1.416499,1.7233782,1.416499,1.416499,1.7233782,1.416499,1.416499,1.416499,1.416499,1.416499,1.416499,1.416499,1.7233782,1.416499,1.7233782,1.7233782,1.416499,1.7233782,1.416499,1.416499,1.416499,1.9327385,1.7233782,1.416499,1.416499,1.8575197,1.7233782,1.7233782,1.416499,1.416499,1.7233782,1.7233782,1.416499,1.416499,1.416499,1.7233782]}},"payload":{"ordinal":10,"text":"[Document context]
