const sampleMetrics = ["count", "avg_cost"];

describe("validatePivotTableConfig", () => {
    it("should pass validation for valid configurations", () => {
      const validConfig: PivotTableConfig = {
        dimensions: ["model"],
        metrics: ["count"],
        rowLimit: 20,
      };

expect(() => validatePivotTableConfig(validConfig)).not.toThrow();
    });

it("should pass validation for valid dimension counts", () => {
      const configWithNoDimensions: PivotTableConfig = {
        dimensions: [],
        metrics: ["count"],
      };
      const configWithOneDimension: PivotTableConfig = {
        dimensions: ["dim1"],
        metrics: ["count"],
      };
      const configWithTwoDimensions: PivotTableConfig = {
        dimensions: ["dim1", "dim2"],
        metrics: ["count"],
      };

expect(() =>
        validatePivotTableConfig(configWithNoDimensions),
      ).not.toThrow();
      expect(() =>
        validatePivotTableConfig(configWithOneDimension),
      ).not.toThrow();
      expect(() =>
        validatePivotTableConfig(configWithTwoDimensions),
      ).not.toThrow();
    });

it("should throw error for empty metrics", () => {
      const invalidConfig: PivotTableConfig = {
        dimensions: ["model"],
        metrics: [],
      };

expect(() => validatePivotTableConfig(invalidConfig)).toThrow(
        "At least one metric is required for pivot table",
      );
    });

it("should throw error for invalid row limit", () => {
      const invalidConfig: PivotTableConfig = {
        dimensions: ["model"],
        metrics: ["count"],
        rowLimit: 0,
      };

expect(() => validatePivotTableConfig(invalidConfig)).toThrow(
        "Row limit must be a positive number",
      );
    });","content_hash":"a9b0acfeca340e9c7f0d13bb0376b5ba06f21a3dcd1eb12b6d6186dc21cc9355","chunk_metadata":{"ordinal":1,"document_path":"/code/langfuse/web/src/__tests__/server/pivot-table-utils.servertest.ts","document_kind":"source","workspace":"person/sana-farid/issue-15208-weighted","team":""}}},"conflict_id":null,"change_id":"qdrant:6efc4b274959d265e64dbf9b"},{"table":"knowledge","key":{"id":"enterprise_5a5666d4329b062e81336635:00002"},"change":"modified","before":{"id":"enterprise_5a5666d4329b062e81336635:00002","vector":{"bm25":{"indices":[70186382,212648289,243686474,448220673,454222729,481329573,548955463,757424159,766710245,772165269,806276788,859155280,926244272,1263925004,1264846464,1303077409,1519078073,1539641452,1646993830,1676405609,1769147305,1801964169,1853176582,1990473719,2027491601,2045916435],"values":[1.5123523,1.9104477,1.5123523,1.5123523,1.5123523,1.7924888,1.7924888,1.7924888,1.5123523,1.5123523,1.9754472,1.5123523,1.5123523,1.5123523,1.9104477,1.7924888,1.5123523,1.5123523,1.9754472,1.7924888,1.9104477,1.5123523,1.5123523,1.5123523,1.7924888,1.5123523]}},"payload":{"chunk_id":"enterprise_5a5666d4329b062e81336635:00002","document_id":"enterprise_5a5666d4329b062e81336635","content_hash":"becb46ef495d26255a07f7982c7477d75bcc6d6481e44ac157156afd7f4cbd6f","ordinal":2,"chunk_metadata":{"document_path":"/code/langfuse/web/src/__tests__/server/pivot-table-utils.servertest.ts","connector":"codebase","repository":"langfuse","ordinal":2,"workspace":"langfuse","language":"ts","document_kind":"source"},"text":"[Document context]
